ValidationRule.errorConditionFormula:
AND(
    NOT($Setup.Case_Validation_Bypass__c.Bypass_Validation__c),
    AND(
    ISPICKVAL(CaseCategory__c, "Duplicate Case"),
    NOT(
        OR(
            $Profile.Name = "System Administrator",
            $Profile.Name = "Call Center Super Manager"
        )
    )
)
)
